  function operationsPage() { const p = overview.operations.production;content.innerHTML = heading('运行与资源', 'Worker、队列与容量直接来自现有运行时。就绪与实际运行保持区分，管理面不调高生产并发。') + `${resourceSummary(overview.operations)}<p><a href="/admin/infrastructure">查看服务器资源、服务拓扑与存储趋势</a></p>` + cards([['正在执行',String(p.active_executions),'来自有效 allocation'],['当前队列',String(p.queue_depth),'展示最早的 100 条记录'],['可用名额',String(p.available_slots),'扣除有效占用并检查心跳'],['Worker',String(p.workers.length),'已登记执行资源']]) + `<section class="admin-panel"><h2>执行资源</h2>${table(['Worker','状态','容量','当前执行','可用','最后心跳'],p.workers.map(w => [esc(w.name || w.worker_id),status(w.status),esc(w.capacity.max_concurrency),esc(w.active_execution_count),esc(w.available_slots),esc(date(w.last_heartbeat_at || w.heartbeat_at))]))}</section><section class="admin-panel"><h2>等待与执行队列</h2>${table(['Execution','状态','等待原因','入队时间','经过时间'],p.queue.map(q => [esc(q.work_title || q.objective || '已登记生产任务'),status(q.condition),esc(q.wait_reason || '运行时未报告等待原因'),esc(date(q.enqueued_at)),`${Math.floor(q.elapsed_seconds / 60)} 分钟`]))}</section>`; }
