    const receipt=tool?receipts.get(String(d.id)):null,output=receipt?.detail?.output;
    const receiptInterval=receipt?.timestamp&&event.timestamp?new Date(receipt.timestamp)-new Date(event.timestamp):null;
    const duration=observation.transport?.elapsed_ms ?? (d.started_at&&d.finished_at?new Date(d.finished_at)-new Date(d.started_at):receiptInterval);
    let state=event.state || (typeof d.result==='string'?d.result:null) || d.condition || d.status;
    let resultLabel=null;
    if(tool){state=output?.exit_code==null?null:output.exit_code===0?'PASS':'FAIL';resultLabel=output?.exists===false?'文件不存在':receipt?'已返回工具结果':'未采集工具回执';}
    if(event.source_ref?.startsWith('self_refine_events:')){action=d.diagnostic_evidence?.signal==='SCOPE_INFLATION'?'发现产物超出批准范围':'处理未满足的局部生产义务';state=null;resultLabel=d.final_result==='LOCAL_OBLIGATION_RECOVERED'?'已自修复':d.final_result || '恢复结果未采集';}
