    const guard=t.guardian.at(-1),elapsed=t.elapsed_seconds;
    content.innerHTML=heading(t.scene || '生产历程','场景与生产结论分别呈现；展开精确证据，未观测保持未知。')+
      `<div class="admin-summary-strip admin-trace-header"><span>结果 <strong>${esc(d.quality_label)}</strong></span><span>耗时 <strong>${elapsed==null||Number(elapsed)<=0?'未采集':Number(elapsed).toFixed(1)+'s'}</strong></span><span>PWU <strong>${t.units.length} 个已记录</strong></span><span>Self-Refine <strong>${d.repair_count??t.recovery.length} 次已记录</strong></span><span>Candidate <strong>${t.candidate.some(c=>c.condition==='SEALED')?'已封存':t.candidate.length?'已记录':'未记录'}</strong></span><span>Guardian ${guard?status(guard.gate || guard.status):'未记录'}</span></div><p>${esc(d.production_result)}</p>`+
      `<div class="admin-actions"><button class="button ${mode==='story'?'':'secondary'}" data-trace-mode="story" aria-pressed="${mode==='story'}">故事视图</button><button class="button ${mode==='diagnostic'?'':'secondary'}" data-trace-mode="diagnostic" aria-pressed="${mode==='diagnostic'}">诊断视图</button><button class="button secondary" data-back-quality>返回质量</button>${t.detail_level==='summary'?'<button class="button secondary" data-trace-details>读取执行详情与完整工程证据</button>':''}</div>`+
      `<div class="admin-trace-tabs" role="tablist" aria-label="生产历程阶段">${traceTabs.map(([key,label])=>`<button id="trace-tab-${key}" role="tab" type="button" data-trace-tab="${key}" aria-selected="${key===traceTab}" aria-controls="trace-panel" tabindex="${key===traceTab?'0':'-1'}">${label}</button>`).join('')}</div><section class="admin-panel admin-trace-panel" id="trace-panel" role="tabpanel" aria-labelledby="trace-tab-${traceTab}">${mode==='diagnostic'?`<div class="admin-alert"><strong>最早可证明的偏离</strong><p>${esc(d.divergence_label)}。未观测阶段不自动视为通过。${esc(d.safety)}；独立保证与确定性判据不能互相替代。</p></div>`:''}${traceSection(traceTab)}</section><details class="admin-panel"><summary>高级工程证据、精确身份与来源</summary><button class="button secondary" data-trace-raw>展开完整原始事件流</button><div id="trace-raw-evidence"></div></details>`;
