  function contextContent(o) {if(o.context_class==='PRODUCT_INTENT'){try{const x=JSON.parse(o.content);return x.desired_outcome || x.human_motive || o.content;}catch {}}return o.content;}
  function resourceSummary(o) {const n=o.node || {};return `<section class="admin-panel"><h2>服务器与服务</h2>${table(['资源','实测'],[['CPU',measured(n.cpu_percent,'%')],['内存',n.memory?`${bytes(n.memory.used_bytes)} / ${bytes(n.memory.total_bytes)}`:'未采集'],['磁盘',n.disk?`${bytes(n.disk.used_bytes)} / ${bytes(n.disk.total_bytes)}`:'未采集'],['网络',n.network?Object.entries(n.network).map(([k,v])=>`${k} 收 ${bytes(v.rx_bytes)} / 发 ${bytes(v.tx_bytes)}`).join('；'):'未采集']])}${table(['服务','状态'],(o.services || []).map(x=>[esc(x.service),status(x.health || x.state)]))}<p class="admin-muted">主机观测：${status(o.state)} ${esc(date(n.observed_at))}；服务观测：${status(o.resource_freshness?.services?.state)} ${esc(date(o.resource_freshness?.services?.observed_at))}；存储观测：${status(o.resource_freshness?.storage?.state)} ${esc(date(o.resource_freshness?.storage?.observed_at))}；未采集或过期观测不能证明当前资源充足。</p></section>`;}
  function contextView(contexts) {return contexts?.length?contexts.map(c=>`<p>上下文合同：${c.contract_id==='MANAGED_GREENFIELD_PRODUCTION'?'首次受治理生产':c.contract_id==='PRODUCT_UI_CHANGE'?'既有产品修改':'已记录的决策上下文'}。</p>${c.missing_classes?.length?`<p>缺少：${c.missing_classes.map(classLabel).map(esc).join('、')}；生产保持关闭。</p>`:''}${table(['保护的事实','当时的内容'],(c.protected_obligations || []).map(o=>[esc(classLabel(o.context_class)),esc(contextContent(o))]))}<p class="admin-muted">未建立且不适用的不变量或产品决定不会凭空补造。</p>${evidence({fingerprint:c.package_fingerprint,generated_from:c.generated_from,selected_files:c.source_references,...c})}`).join(''):'<p>未采集当时的上下文；不能以今天的上下文替代。</p>';}
